original.qasm:
OPENQASM 3.0;
include "stdgates.inc";
bit[1] c;
qubit[1] q;
qubit[1] psi;
U(pi/2, 0, pi) q[0];
U(pi, pi/4, -pi) psi[0];
cx psi[0], q[0];
U(0, 0, -pi/4) q[0];
cx psi[0], q[0];
U(pi/2, 0, -3*pi/4) q[0];
barrier q[0], psi[0];
c[0] = measure q[0];

